(function () {
  var authEnabled = (pm.variables.get('auth_enabled') || '').toLowerCase() === 'true';
  if (!authEnabled) return;

  var reqPath = pm.request.url.getPath();
  if (reqPath.indexOf('/health') !== -1) return;

  var bodyRaw = '';
  if (pm.request.body && pm.request.body.mode === 'raw') {
    // pm.request.body.raw is the unresolved template — {{participant_id}}
    // is still literal text here, Postman only substitutes collection/env
    // variables into the body when it builds the outgoing request, which
    // happens AFTER this script runs. Signing the unresolved template would
    // produce a signature over different bytes than what the server
    // actually receives (guaranteed 401 for any body using a variable).
    // pm.variables.replaceIn() resolves {{...}} the same way Postman's own
    // request builder will, so the digest matches what goes over the wire.
    bodyRaw = pm.variables.replaceIn(pm.request.body.raw || '');
  }

  var privateKey = pm.variables.get('registry_private_key');
  var subscriberId = pm.variables.get('subscriber_id');
  var ukId = pm.variables.get('unique_key_id');

  if (!privateKey || !subscriberId || !ukId) {
    console.warn('credential-service collection: auth_enabled=true but registry_private_key/subscriber_id/unique_key_id are not set; sending request unsigned.');
    return;
  }

  var header = OndcAuth.createAuthorizationHeader({
    body: bodyRaw,
    privateKey: privateKey,
    subscriberId: subscriberId,
    ukId: ukId
  });

  pm.request.headers.upsert({ key: 'Authorization', value: header });
})();
